INSERT INTO fut_evolution_log VALUES(1,25,2489,'Repeat Delivery',1,'2026-09-19','2026-09-19',70,78,'{"PAC": 76, "SHO": 65, "PAS": 65, "DRI": 73, "DEF": 34, "PHY": 60}','{"PAC": 76, "SHO": 65, "PAS": 65, "DRI": 73, "DEF": 34, "PHY": 60}',NULL,'["Inventive"]','[]','[]','scripts/fut_club.py evolve (2026-09-19 기록) · 2026-09-19 사용자 정정: 밟은 진화는 Repeat Delivery(반복 배급)였다','MEASURED(사용자 행위) — 진화 식별은 사용자 보고. 완주 시 OVR은 fut.gg 경로 단계값(+8)','반복 배급(Repeat Delivery) 시작 — 진행 중. 단계1: OVR+8 · 짧은패스+15 · 균형+12 · 침착+10 · 질주+5 (훈련 캠프) · 2026-09-19 GG Club 싱크로 완주 확인(EA OVR 78)',0,NULL);
INSERT INTO fut_evolution_log VALUES(2,30,2494,'Striker Glow Up [SP 7]',1,'2026-09-19',NULL,65,65,'{"PAC": 70, "SHO": 65, "PAS": 50, "DRI": 58, "DEF": 22, "PHY": 74}','{"PAC": 77, "SHO": 79, "PAS": 56, "DRI": 69, "DEF": 22, "PHY": 77}',NULL,'["Game Changer"]','[44]','[]','scripts/fut_club.py evolve (2026-09-19 기록) · 적용 후 값 출처: player_evolutions.path_json (fut.gg 계산 결과 카드)','REJECTED — 2026-09-19 GG Club 싱크에서 마조 카드가 66(기본 65 + 반복 소개 1차)으로 확인됐다. 이 진화는 실제로 적용되지 않았다','추천 1순위 Striker Glow Up [SP 7] · 4레벨 진행 · ⛔ 2026-09-19 실측으로 무효 확인 — 적용되지 않은 진화다(해당 진화는 아직 미사용) · [2026-09-20] is_void=1 — 소진 계산에서 제외한다(이 진화는 아직 미사용이므로 다른 선수가 쓸 수 있다).',1,NULL);
INSERT INTO fut_evolution_log VALUES(3,30,2492,'Intro to Repeatable Evolutions',1,'2026-09-19','2026-09-19',65,66,'{"PAC": 70, "SHO": 65, "PAS": 50, "DRI": 58, "DEF": 22, "PHY": 74}',NULL,NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-19 기록) · 적용 후 값 출처: 카탈로그 levels[0] 총상승(Overall +1). ⚠️ fut.gg path_json은 기본 카드(65) 기준이라 쓰지 않았다','MEASURED(사용자 행위) — 적용·완료는 사용자 보고. OVR은 카탈로그 상승폭 +1을 현재값 75에 더한 값이고, 6대 스탯 변화는 EA가 공개하지 않아 미기록(결손이지 0이 아니다)','반복 가능 진화 소개(Intro to Repeatable Evolutions) 1차 — 사용자 보고 2026-09-19. 시야+3·짧은패스+3·중거리슛+4·반응력+4 · 2026-09-19 정정: Glow Up 무효 확인으로 기준이 기본 카드 65였다 [2026-09-25 정정] ⛔ six_before가 **무효 행(Striker Glow Up · 적용된 적 없음)의 산출값**이었다 — 기준 카드 값으로 바로잡았다. OVR 체인도 65→66으로 맞췄다.',0,NULL);
INSERT INTO fut_evolution_log VALUES(4,30,2488,'Intro to Pathway Evolutions',1,'2026-09-19','2026-09-19',66,66,NULL,NULL,NULL,'["Game Changer"]',NULL,NULL,'scripts/fut_club.py evolve (2026-09-19 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED — 2026-09-19 사용자 확인: 게임 체인저 부여 확인. 능력치 변화 없는 진화(PlayStyle 전용)','경로 진화 소개(Intro to Pathway Evolutions) 시작 — PlayStyle 선택 **게임 체인저(Game Changer)** 확정(2026-09-19 사용자 결정, 대안은 인벤티브). 능력치 상승 없음, PlayStyle만 부여 · 챌린지: 스쿼드 배틀 세미프로 이상 1경기 · [2026-09-19 완주] 게임 체인저 붙음(사용자 확인). fut.gg 싱크에서도 OVR·스탯 변화 없음으로 정합 [2026-09-25 정정] ⛔ ovr_before/after가 **76**으로 적혀 있었다 — 마조는 76이었던 적이 없다(무효 행의 산출값이 샜다). 이 진화는 PlayStyle만 주므로 66→66이 맞다. six_before는 직후 스냅샷이 없어 결손으로 둔다(불변규칙 3).',0,NULL);
INSERT INTO fut_evolution_log VALUES(5,48,2490,'Intro to Training Camp EVOs',1,'2026-09-19','2026-09-19',78,78,'{"PAC": 79, "SHO": 51, "PAS": 68, "DRI": 73, "DEF": 76, "PHY": 73}','{"PAC": 79, "SHO": 51, "PAS": 68, "DRI": 73, "DEF": 76, "PHY": 73}',NULL,'["Rapid", "Block", "Intercept", "Anticipate", "Slide Tackle+"]','[24, 3, 5]','[]','scripts/fut_club.py evolve (2026-09-19 기록) · 적용 후 값 출처: player_evolutions.path_json (fut.gg 계산 결과 카드)','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 player_evolutions.path_json (fut.gg 계산 결과 카드).','훈련 캠프 진화 소개(Intro to Training Camp EVOs) 시작 — 보상은 Role+ RB 풀백(OVR 변화 없음)',0,NULL);
INSERT INTO fut_evolution_log VALUES(6,49,2502,'Fullback Fork',1,'2026-09-19','2026-09-19',78,80,'{"PAC": 78, "SHO": 61, "PAS": 74, "DRI": 71, "DEF": 73, "PHY": 75}','{"PAC": 82, "SHO": 61, "PAS": 74, "DRI": 71, "DEF": 78, "PHY": 78}',NULL,'["Whipped Pass", "Jockey", "Inventive"]','[9, 28]','[]','scripts/fut_club.py evolve (2026-09-19 기록) · 적용 후 값 출처: player_evolutions.path_json (fut.gg 계산 결과 카드)','MEASURED — 2026-09-19 GG Club 싱크로 완주·결과 확인(OVR 80). ⚠️ 카탈로그 단계 표기(+5)로 계산한 83과 달랐다','풀백의 갈림길(Fullback Fork) 시작 — 3단계 선택 **자키(Jockey)** 확정(2026-09-19 사용자 결정). 예정 상승: 1단계 OVR+5·질주+5·수비위치+5·슬라이딩+5 → 2단계 가속+5·차단+5·스탠딩+5·체력+5 → 3단계[자키] PlayStyle 자키·헤딩+5·점프+5·힘+5·공격성+5. 완주 시 OVR 78→83 · [2026-09-19 정정] 완주 실측 78→80. 카탈로그 「Overall +5」는 EA 실제 산출과 일치하지 않는다 · [2026-09-20 더블체크] ⛔ playstyles_after의 **Inventive는 EA에 없다**(실측 [9,10] = Whipped Pass + Jockey). 기준 카드 Whipped Pass + 3단계 선택 Jockey로 실측이 완전히 설명된다. path_json을 실측 대신 쓴 결과다.',0,NULL);
INSERT INTO fut_evolution_log VALUES(7,25,2489,'Repeat Delivery',2,'2026-09-19','2026-09-19',78,78,'{"PAC": 78, "SHO": 65, "PAS": 73, "DRI": 74, "DEF": 34, "PHY": 64}',NULL,NULL,NULL,NULL,NULL,'fut.gg GG Club 싱크(2026-09-19) + 사용자 확인 「진화 3단계 완료」','MEASURED — 완주는 사용자 확인, 결과 6대 스탯은 EA 싱크 실측. 단계별 중간값은 미보유(최종만 기록)','반복 배급 2단계 — 긴 패스+12·반응력+12·시야+15·체력+15 · PlayStyle 핑드 패스',0,NULL);
INSERT INTO fut_evolution_log VALUES(8,25,2489,'Repeat Delivery',3,'2026-09-19','2026-09-19',78,78,'{"PAC": 78, "SHO": 65, "PAS": 73, "DRI": 74, "DEF": 34, "PHY": 64}','{"PAC": 78, "SHO": 65, "PAS": 73, "DRI": 74, "DEF": 34, "PHY": 64}',NULL,NULL,NULL,NULL,'fut.gg GG Club 싱크(2026-09-19) + 사용자 확인 「진화 3단계 완료」','MEASURED — 완주는 사용자 확인, 결과 6대 스탯은 EA 싱크 실측. 단계별 중간값은 미보유(최종만 기록)','반복 배급 3단계 — 볼컨트롤+8·크로스+10·커브+12 · 약발 +2★ · PlayStyle 퍼스트 터치',0,NULL);
INSERT INTO fut_evolution_log VALUES(9,25,2489,'Repeat Delivery',4,'2026-09-19','2026-09-19',78,78,NULL,'{"PAC": 78, "SHO": 65, "PAS": 76, "DRI": 75, "DEF": 34, "PHY": 64}',NULL,NULL,NULL,NULL,'fut.gg GG Club 싱크(2026-09-19) — 아이템 반복 접미 -3 · PAS 73→76 · DRI 74→75','MEASURED — EA 싱크 실측. 4단계 보상(스킬무브 +2★·가속·민첩·드리블)과 방향 일치','반복 배급 4단계(최종) — 싱크 실측으로 확인. 스킬무브 +2★·프리킥 정확도+4·가속+5·민첩성+8·드리블+8',0,NULL);
INSERT INTO fut_evolution_log VALUES(10,25,2489,'Repeat Delivery',4,'2026-09-20','2026-09-20',78,78,'{"PAC": 80, "SHO": 65, "PAS": 76, "DRI": 75, "DEF": 34, "PHY": 64}','{"PAC":80,"SHO":65,"PAS":76,"DRI":75,"DEF":34,"PHY":64}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-20 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','반복 배급 1회차 **최종(4/4) 완주** — 2026-09-20 GG Club 싱크 실측(아이템 접미 -4). ⭐ 4단계 보상의 가속+5가 이제 반영됐다: PAC 78→80(PAC=가속.45+질주.55 구성식과 정합). ⚠️ 정정: 09-19에 기록한 level 4 행(log #9, 접미 -3)은 실제로는 **3단계**였다 — 그때 오른 것은 PAS 73→76·DRI 74→75로 3단계 보상(볼컨트롤+8·크로스+10·커브+12)과 일치한다. ⇒ **접미 -N = N단계 완료**가 맞는 대응이다. 카탈로그상 2489는 4단계·repeatability 2이므로 Alysson은 이제 1회차를 닫았고 2회차가 가능하다. · [2026-09-20 더블체크] ⛔ log#1의 playstyles_after ["Inventive"]는 **오기**다 — 반복 배급은 Inventive를 주지 않는다(2단계 핑드 패스·3단계 퍼스트 터치). EA 실측 [19,6]로 확인했고 fut_club_players.current_playstyles를 채웠다. 원인은 path_json(계산 결과 카드)을 실측 대신 쓴 것 — 루제리 OVR 83↔실측 80과 같은 부류다. | ⛔ 중복 기록 — 무효(2026-09-20 사용자 지적 「진화상태가 4회짜리인데 5회로 나옴」). id=9가 2026-09-19 싱크로 이미 Repeat Delivery **4단계 완료**를 닫았는데, 09-20에 같은 4단계를 사용자 입력값으로 다시 적재해 행이 하나 더 생겼다(같은 진화의 같은 단계는 한 번만 존재한다). 값은 두 행이 동일(78→78)이라 스탯 영향은 없고 **횟수만 1 부풀렸다**. 원장 규약상 지우지 않고 is_void로 무효 처리한다(불변규칙 2).',1,NULL);
INSERT INTO fut_evolution_log VALUES(11,30,2492,'Intro to Repeatable Evolutions',1,'2026-09-20','2026-09-20',66,67,'{"PAC": 70, "SHO": 68, "PAS": 54, "DRI": 62, "DEF": 22, "PHY": 74}','{"PAC":70,"SHO":68,"PAS":54,"DRI":62,"DEF":22,"PHY":74}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-20 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','반복 가능 진화 소개 **2회차**(사용자 확인 「2번 돌린거야」) — 아이템 접미 -1 → -2 · OVR 66→67. ⭐ 1회차와 같은 **1단계 보상(Overall +1)**이 다시 들어온 것이라 2회차 1단계로 기록한다(2단계 보상에는 Overall 상승이 없다 — 슛파워+3·발리+3·FK+4·롱패스+4·드리블+4). 카탈로그 repeatability=2와 정합하며 이로써 **이 진화는 소진**됐다. [2026-09-25 정정] ovr_before가 67(=적용 후 값)로 들어가 있었다 — 주석의 「OVR 66→67」대로 66으로 바로잡았다(런북 「ovr_before에 현재값이 들어간다」 함정).',0,NULL);
INSERT INTO fut_evolution_log VALUES(12,146,2489,'Repeat Delivery',1,'2026-09-20','2026-09-20',65,73,'{"PAC": 82, "SHO": 60, "PAS": 70, "DRI": 68, "DEF": 40, "PHY": 61}','{"PAC":82,"SHO":60,"PAS":70,"DRI":68,"DEF":40,"PHY":61}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-20 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','반복 배급(Repeat Delivery) **시작** — 사용자 보고 「알리송이 했던 진화 시작」(2026-09-20). 완주 시 1단계 OVR+8(73→81 예상) · 질주+5 · 침착+10 · 균형+12 · 짧은패스+15. ⚠️ 진행 중이라 **스탯은 현재값 그대로** 둔다(--in-progress) — 완주 시 complete로 반영한다. ⛔ fut.gg는 진화 경로를 주지 않으므로 이 귀속은 **사용자 보고**가 유일 근거다. ⭐ 이 카드는 2026-09-20 3,700코인 입수 신규분이고 선발 스쿼드에 들어 있다. · [2026-09-20 정정] ⛔ 이 행을 「시작(진행 중)」으로 적은 것은 **전제가 틀렸다** — 기록 시점에 이미 **1단계가 적용돼 있었다**(기준 카드 65 → 클럽 카드 73 = Overall +8). ovr_before를 73에서 **65**로 바로잡고 완료 처리했다. 사용자 확인으로 2단계까지 완주했음이 확인돼 별도 행을 추가했다.',0,NULL);
INSERT INTO fut_evolution_log VALUES(13,146,2489,'Repeat Delivery',2,'2026-09-20','2026-09-20',73,73,'{"PAC":82,"SHO":60,"PAS":70,"DRI":68,"DEF":40,"PHY":61}','{"PAC":82,"SHO":60,"PAS":70,"DRI":68,"DEF":40,"PHY":61}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-20 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','반복 배급 2단계 완주 — 사용자 확인 「지모알로바는 2단계까지 했어」(2026-09-20). ⭐ EA 실측 PlayStyle **핑드 패스(id 6)**가 2단계 보상과 일치하고, 기준 카드(ea 76255, OVR 65)에는 PS가 없으므로 **온전히 진화분**이다. 2단계 보상: 핑드 패스 · 긴 패스+12 · 반응력+12 · 시야+15 · 체력+15(6대 스탯 이동은 EA 실측 기준 없음).',0,NULL);
INSERT INTO fut_evolution_log VALUES(14,146,2489,'Repeat Delivery',3,'2026-09-21','2026-09-21',73,73,'{"PAC": 82, "SHO": 60, "PAS": 73, "DRI": 74, "DEF": 40, "PHY": 61}',NULL,NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-21 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','반복 배급 3단계 — 사용자 확인 「반복배급은 완료했어 4단계까지」(2026-09-21). 보상: 볼컨트롤+8(캡74)·크로스+10(78)·커브+12(78)·약발+2★(캡3)·PlayStyle 퍼스트 터치. ⛔ 약발은 이미 3★라 실이득 0. 3단계 시점의 6대 스탯은 실측하지 않았다(싱크는 4단계 완주 후에 돌렸다) — 값은 4단계 행에만 적는다.',0,NULL);
INSERT INTO fut_evolution_log VALUES(15,146,2489,'Repeat Delivery',4,'2026-09-21','2026-09-21',73,73,NULL,'{"PAC":82,"SHO":60,"PAS":73,"DRI":74,"DEF":40,"PHY":61}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-21 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','반복 배급 4단계(최종) 완주 — 2026-09-21 GG Club 싱크 **EA 실측**. 보상: 스킬무브+2★(캡3)·FK정확도+4(80)·가속+5(캡80)·민첩성+8(78)·드리블+8(74). ⛔ 스킬무브는 이미 3★, 가속은 84로 캡 초과라 둘 다 실이득 0. ⭐ 실측 82/60/73/74/40/61은 기준 카드(65) 속성에 1~4단계 델타를 캡까지 적용한 재구성과 **6개 전부 일치**한다(PAS 70→73·DRI 68→74가 3·4단계분). EA PlayStyle [19,6]=퍼스트 터치+핑드 패스 = 3단계·2단계 보상이고 기준 카드엔 PS가 없었다. ⚠️ 아이템 접미는 -1뿐이다 — 접미를 단계 근거로 쓰지 말라는 규약(obs#904)의 재확인 사례. ⭐ 이로써 반복 배급은 알리송 1회차 + 이 카드 2회차로 **repeatability 2 소진**(사용자 확인 2026-09-21).',0,NULL);
INSERT INTO fut_evolution_log VALUES(16,146,2506,'Creative Crossroads',1,'2026-09-21','2026-09-21',73,78,'{"PAC": 82, "SHO": 60, "PAS": 73, "DRI": 74, "DEF": 40, "PHY": 61}',NULL,NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-21 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','Creative Crossroads 1단계(OVR+5·질주/슈팅력/FK/커브/균형 각 +7). ⚠️ 1단계 직후 6대 스탯은 미측정 — 사용자가 2단계까지 적용한 뒤 값을 확인했다(결손은 NULL).',0,NULL);
INSERT INTO fut_evolution_log VALUES(17,146,2506,'Creative Crossroads',2,'2026-09-21','2026-09-21',78,78,NULL,'{"PAC":83,"SHO":62,"PAS":74,"DRI":75,"DEF":40,"PHY":62}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-21 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','Creative Crossroads 2단계(가속/공격위치/발리/짧은패스/민첩 +7 · 체력 +5). 6대 스탯은 인게임 실측(사용자 보고) — 1·2단계 누적값이다. ⛔ 3단계는 옵션 2(Shadow Striker+ · Low Driven Shot) 예정, 마감 09-30 17:00 UTC.',0,NULL);
INSERT INTO fut_evolution_log VALUES(18,49,2502,'Fullback Fork',2,'2026-09-19','2026-09-19',80,80,NULL,NULL,NULL,NULL,NULL,NULL,'원장 정정 2026-09-22 — 기준 카드 29속성 + 카탈로그 단계별 보상(캡 적용) 재구성이 EA 실측 6대 스탯과 **6/6 일치**해 단계를 확정했다. 3단계 분기는 PlayStyle로 갈렸다: 옵션1=Pinged Pass · 옵션2=Jockey인데 카드의 실제 PlayStyle이 「Whipped Pass(기준) + Jockey」라 **옵션 2** 확정.','MEASURED(재구성 검증). ⚠️ 적용일은 1단계와 같은 2026-09-19로 둔다 — 실제 단계별 날짜는 기록되지 않았다(결손). ⛔ OVR은 1단계에서 이미 캡(^80)에 도달해 2·3단계로 더 오르지 않는다.','가속·차단력·스탠딩 태클 +5 · 체력 +5(캡 76 < 원값 82라 실이득 0)',0,NULL);
INSERT INTO fut_evolution_log VALUES(19,49,2502,'Fullback Fork',3,'2026-09-19','2026-09-19',80,80,NULL,NULL,NULL,NULL,NULL,NULL,'원장 정정 2026-09-22 — 기준 카드 29속성 + 카탈로그 단계별 보상(캡 적용) 재구성이 EA 실측 6대 스탯과 **6/6 일치**해 단계를 확정했다. 3단계 분기는 PlayStyle로 갈렸다: 옵션1=Pinged Pass · 옵션2=Jockey인데 카드의 실제 PlayStyle이 「Whipped Pass(기준) + Jockey」라 **옵션 2** 확정.','MEASURED(재구성 검증). ⚠️ 적용일은 1단계와 같은 2026-09-19로 둔다 — 실제 단계별 날짜는 기록되지 않았다(결손). ⛔ OVR은 1단계에서 이미 캡(^80)에 도달해 2·3단계로 더 오르지 않는다.','옵션 2 — PlayStyle Jockey · 헤딩 +5 · 점프 +5(캡 75 < 원값 80이라 0) · 힘 +5 · 공격성 +5(캡 76 < 원값 77이라 0)',0,NULL);
INSERT INTO fut_evolution_log VALUES(20,145,2491,'Intro to Evolutions',1,'2026-09-22','2026-09-22',73,79,'{"PAC": 56, "SHO": 59, "PAS": 72, "DRI": 70, "DEF": 73, "PHY": 68}','{"PAC": 68, "SHO": 59, "PAS": 72, "DRI": 70, "DEF": 74, "PHY": 68}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-22 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','2026-09-22 사용자 보고 「본머스 선수에게 적용」. 기준 카드 OVR 73 → 현재 79로 6대 스탯이 전부 진화 상한과 일치해 확정(PAC 56→80 ^80 · DRI 70→79 ^80 · DEF 73→76 ^76). fut.gg는 경로를 주지 않아 스탯 대조로 판정(런북 §3-2 단계 판정 순서 ⑴⑵). ⚠️ 2026-09-27 migration 083 보정: 종전 `evolve`가 **1단계 행만** 넣어 이 단계가 누락돼 있었다(scripts/evo_detect.py --verify가 EA 실측과 대조해 찾아냈다). 값은 기준 카드에 카탈로그 보상을 상한 규칙대로 얹어 재계산했고, 재계산 결과가 EA 실측 29속성과 **전부 일치**하는 것을 확인했다(등급 B→C).',0,'{"가속": 54, "질주 속도": 80, "공격 위치 선정": 65, "결정력": 50, "슈팅력": 72, "중거리슛": 68, "발리 슛": 43, "페널티킥": 55, "시야": 68, "크로스": 73, "프리킥 정확도": 65, "짧은 패스": 76, "긴 패스": 69, "커브": 71, "민첩성": 65, "균형 감각": 77, "반응력": 75, "볼컨트롤": 74, "드리블": 68, "침착": 70, "차단력": 76, "헤딩 정확도": 69, "수비 위치 선정": 74, "스탠딩 태클": 75, "슬라이딩 태클": 75, "점프": 68, "체력": 64, "힘": 68, "공격성": 73}');
INSERT INTO fut_evolution_log VALUES(21,144,2507,'Midfield Glow Up',1,'2026-09-23','2026-09-23',74,79,'{"PAC": 66, "SHO": 53, "PAS": 67, "DRI": 70, "DEF": 72, "PHY": 69}',NULL,NULL,'["Tiki Taka", "Inventive"]','[4, 14, 16, 49, 18]','[]','scripts/fut_club.py evolve (2026-09-23 기록) · 2026-09-24 EA 실측으로 정정','MEASURED(사용자 행위) — OVR은 EA 실측 확정. 6대 스탯은 단계 분리 불가라 결손.','[2026-09-24 정정] 1단계 완료. ⚠️ 종전에 적혀 있던 six_after는 **4단계 전부를 얹은 카탈로그 산출값**이라 1단계 결과가 아니었다 — 실측으로 확정할 수 없어 NULL로 둔다(불변규칙 3): 1단계 직후의 EA 스냅샷이 없고, 가장 이른 캡처(2026-09-23 23:13)가 이미 2단계까지 반영된 상태였다. OVR 79는 확정이다(1단계 보상 자체가 Overall +40 ^79이고 그 캡처가 79였다). 원 기록: 인게임 1단계 진행(2026-09-23 사용자 확인 「보가르데는 1단계 진화 진행중」) · 단독 적용(요구조건 OVR Max 74·CDM·PS 7·속도 Max 85).',0,NULL);
INSERT INTO fut_evolution_log VALUES(22,144,2507,'Midfield Glow Up',2,'2026-09-23','2026-09-23',79,79,NULL,'{"PAC": 66, "SHO": 53, "PAS": 74, "DRI": 70, "DEF": 74, "PHY": 74}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-24 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','2단계 완료. EA 실측(2026-09-23 23:13 GG Club 캡처)으로 확정 — 크로스 53→75·커브 58→75·공격성 71→75가 2단계 상한과 일치한다(슬라이딩은 기준 76으로 이미 상한 75 초과라 +0). PlayStyle Tiki Taka(EA id 8)도 이 단계 보상이다. ⚠️ six_before는 결손이다 — 스크립트가 넣은 값이 현재(완주) 상태였고, 1단계 직후 EA 스냅샷이 없어 실측으로 채울 수 없다(불변규칙 3).',0,NULL);
INSERT INTO fut_evolution_log VALUES(23,144,2507,'Midfield Glow Up',3,'2026-09-24','2026-09-24',79,79,'{"PAC": 66, "SHO": 53, "PAS": 74, "DRI": 70, "DEF": 74, "PHY": 74}','{"PAC": 71, "SHO": 53, "PAS": 76, "DRI": 70, "DEF": 74, "PHY": 74}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-24 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','3단계 완료. EA 실측(2026-09-24 10:13 GG Club 캡처) — 가속 65→75·프리킥 43→74·차단력 73→75·점프 70→76이 3단계 상한과 일치하고 Role+ 16(CDM Deep-Lying Playmaker+)이 붙었다.',0,NULL);
INSERT INTO fut_evolution_log VALUES(24,144,2507,'Midfield Glow Up',4,'2026-09-24','2026-09-24',79,79,'{"PAC": 71, "SHO": 53, "PAS": 76, "DRI": 70, "DEF": 74, "PHY": 74}','{"PAC": 75, "SHO": 53, "PAS": 78, "DRI": 70, "DEF": 77, "PHY": 76}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-24 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','4단계 완료 = Midfield Glow Up 완주(2026-09-24 사용자 보고 「보가르데는 진화 완료함」). EA 실측(같은 날 Sync Club 직후 캡처) — 질주속도 67→75·짧은패스 75→80·수비위치선정 72→80·체력 67→76, Role+ 49(CDM Box Crasher+) 추가.',0,NULL);
INSERT INTO fut_evolution_log VALUES(25,146,2506,'Creative Crossroads',3,'2026-09-25','2026-09-25',78,78,'{"PAC": 83, "SHO": 62, "PAS": 74, "DRI": 75, "DEF": 40, "PHY": 62}','{"PAC": 83, "SHO": 67, "PAS": 74, "DRI": 78, "DEF": 40, "PHY": 62}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-25 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','Creative Crossroads 3단계 = **갈림길 2(Shadow Striker) 선택**으로 완주(2026-09-25 사용자 보고 「지모알로바 진화 완료 새도 스트라이커로 진화완료했어」). 보상: Role+ CAM Shadow Striker+(role_plus 32) · PlayStyle Low Driven Shot(id 34) · 결정력 +7(^80) · 중거리슛 +7(^77) · 드리블 +7(^80) · 침착 +7(^76). ⛔ 고른 가지는 fut.gg가 주지 않는다 — 사용자 보고가 유일한 출처다. ⚠️ six_after는 기준 attrs에 상한을 씌운 **산출값**이다(EA 실측 아님): 캡에 걸려 드리블 +6·침착 +2만 올랐다. ⭐ 계산법은 같은 카드의 현재 attrs↔current_six가 6/6 일치해 검증했다. 다음 /club-sync에서 EA 실측으로 확정한다. ⛔ current_playstyles·current_roles_plus는 EA 실측 축이라 여기서 건드리지 않았다.',0,NULL);
INSERT INTO fut_evolution_log VALUES(26,18,2501,'Pinged Pass',1,'2026-09-25','2026-09-25',76,76,'{"DIV": 76, "HAN": 75, "KIC": 76, "REF": 76, "SPD": 56, "POS": 74}','{"DIV":76,"HAN":75,"KIC":76,"REF":76,"SPD":56,"POS":74}',NULL,'Cross Claimer, Deflector, Pinged Pass','[45]','[]','사용자 보고(적용) + fut.gg GG Club API playerDef.playstyles 실측(2026-09-25 싱크)','HIGH — EA 싱크 실측으로 PlayStyle 부여를 확인했다. ⚠️ 단계는 카탈로그상 1단계뿐이라 판정 여지가 없다.','Pep''s Domination 과제로 해금 후 적용(사용자 보고 2026-09-25). 단일 단계·챌린지 0·비용 0 — 보상은 PlayStyle 핑드 패스뿐이라 OVR·6대 스탯 변동 없음. EA 싱크 실측 확인 완료(2026-09-25): playstyles=[33 Deflector, 30 Cross Claimer, 6 Pinged Pass] · playstylesPlus=[] — 카탈로그 표기 (^3)은 PlayStyle+가 아니었다. OVR 76 불변.',0,NULL);
INSERT INTO fut_evolution_log VALUES(27,30,2500,'Believe',1,'2026-09-25','2026-09-25',67,68,'{"PAC": 70, "SHO": 68, "PAS": 54, "DRI": 62, "DEF": 22, "PHY": 74}','{"PAC": 70, "SHO": 68, "PAS": 56, "DRI": 62, "DEF": 22, "PHY": 74}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-25 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED — 적용 사실은 사용자 보고, 결과값은 2026-09-25 EA 싱크 실측으로 확정(OVR·6대 스탯 전부).','Believe 완주(2026-09-25 사용자 보고 「빌리브는 해제해서 마조 진화 완료했고」). 해금 경로: Ted Lasso''s Masterclass 목표 그룹 완료 — 시즌패스가 아니라 목표형 해금이다. 1단계짜리 진화. 보상: Overall +1(^83) · 침착 +3(^84) · 짧은 패스 +4(^83). ⚠️ six_after는 산출값이다(EA 실측 아님) — 두 속성 다 상한 여유가 있어 표기대로 올랐다(침착 59→62 · 짧은 패스 63→67). 계산법은 같은 카드의 현재 attrs↔current_six가 6/6 일치해 검증했다. ⛔ current_playstyles·current_roles_plus는 EA 실측 축이라 건드리지 않았다 — Believe는 PlayStyle·Role 보상이 없어 변화 없음이 예상된다. OVR은 EA 산식 비공개라 산출하지 않고 67을 유지했다(표기 +1은 상한 83 기준이라 67→68일 수 있다 — 다음 /club-sync에서 확정). [2026-09-25 정정] ⭐ EA 실측으로 확정 — OVR은 67이 아니라 **68**이다(저녁 GG Club 싱크가 68로 받아 왔다). 기록 당시 「표기 +1이 상한 83 기준이라 67→68일 수 있다」고 적어 둔 대로 +1이 실제로 들어갔다. ⭐ 6대 스탯 산출값(PAC 70·SHO 68·PAS 56·DRI 62·DEF 22·PHY 74)은 EA 실측과 **6/6 일치**했다 — 상한 규칙 계산법이 또 한 번 검증됐다.',0,NULL);
INSERT INTO fut_evolution_log VALUES(28,30,2508,'Frontline Paradox',1,'2026-09-26','2026-09-26',68,73,'{"PAC": 70, "SHO": 68, "PAS": 56, "DRI": 62, "DEF": 22, "PHY": 74}','{"DEF": 22, "DRI": 62, "PAC": 73, "PAS": 56, "PHY": 74, "SHO": 72}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-26 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','최전방의 역설(Frontline Paradox) 1단계 클리어 — 사용자 보고 2026-09-26. 미션: 세미프로 이상 스쿼드 배틀 1경기(활성 진화 선수 포함). ⭐ 3단계 갈림길은 Trickster(ST Advanced Forward+)로 갈 계획 — 처방을 어드밴스드 포워드로 정정한 것과 같은 축(migration 075). ⚠️ OVR 73·6대 스탯은 카탈로그 보상을 상한 규칙대로 얹은 우리 계산이다(등급 B) — 다음 GG Club 싱크의 EA 실측으로 확정한다. 남은 단계 2·3.',0,NULL);
